import sys

def numberOfEnclaves(grid):
    def dfs(i, j):
        if i < 0 or i >= len(grid) or j < 0 or j >= len(grid[0]) or grid[i][j] == 0:
            return
        grid[i][j] = 0
        dfs(i + 1, j)
        dfs(i - 1, j)
        dfs(i, j + 1)
        dfs(i, j - 1)

    for i in range(len(grid)):
        for j in [0, len(grid[0]) - 1]:
            if grid[i][j] == 1:
                dfs(i, j)
    for i in [0, len(grid) - 1]:
        for j in range(len(grid[0])):
            if grid[i][j] == 1:
                dfs(i,	j)

    return sum(grid[i][j] for i in range(len(grid)) for j in range(len(grid[0])))

def main():
    import sys
    input = sys.stdin.read().strip().split()
    n, m = int(input[0]), int(input[1])
    grid = [[int(input[i * m + j + 2]) for j in range(m)] for i in range(n)]
    print(numberOfEnclaves(grid))

if __name__ == "__main__":
    main()
